      "path": "internal/router/routes_knowledge.go",
      "content": "package router\n\nimport (\n\t\"net/http\"\n\n\t\"github.com/gin-gonic/gin\"\n\n\t\"github.com/Tencent/WeKnora/internal/handler\"\n)\n\n// RegisterChunkerDebugRoutes wires the read-only chunker preview endpoint\n// used by the KB editor's debug panel. Stateless — uses no service deps.\n//\n// Viewer+ floor: the endpoint surfaces inside the tenant UI, so any\n// authenticated tenant member can call it; revoked accounts whose JWT\n// has not yet expired are kept out by the role check, matching the\n// rest of the RBAC matrix in this file.\nfunc RegisterChunkerDebugRoutes(r *gin.RouterGroup, g *rbacGuards) {\n\tg.apiKeyRoute(r, http.MethodPost, \"/chunker/preview\", apiKeyRetrieve(apiKeyIngest(apiKeyFullAccess())), g.Viewer(), handler.PreviewChunking)\n}\n\n// RegisterChunkRoutes 注册分块相关的路由\n//\n// Mutating routes addressed via :knowledge_id inherit per-KB ownership\n// from the owning knowledge entry's KB (PR 5, #1303); the chain hop is\n// shared with RegisterKnowledgeRoutes via OwnedChunkKBOrAdmin so the\n// same \"creator-of-the-KB OR Admin+\" rule applies to chunk edits.\nfunc RegisterChunkRoutes(r *gin.RouterGroup, handler *handler.ChunkHandler, g *rbacGuards) {\n\t// 分块路由组。Scoped API key 需要 ingest 能力写内容，retrieve 能力读内容；\n\t// 两者仍受 KB 白名单约束。\n\tchunks := g.apiKeyGroup(r.Group(\"/chunks\"), apiKeyIngest(apiKeyFullAccess()))\n\tchunkRead := chunks.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// 获取分块列表 — Viewer+ 且对父 KB 有 read 权限（own / shared / via shared agent）\n\t\tchunkRead.GET(\"/:knowledge_id\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"knowledge_id\"), handler.ListKnowledgeChunks)\n\t\t// 通过chunk_id获取单个chunk（不需要knowledge_id） — Viewer+ 且对父 KB 有 read 权限\n\t\tchunkRead.GET(\"/by-id/:id\", g.Viewer(), g.KBAccessReadFromChunkIDParam(\"id\"), handler.GetChunkByIDOnly)\n\t\tchunkRead.GET(\"/:knowledge_id/:id/revisions\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"knowledge_id\"), handler.ListChunkRevisions)\n\t\t// 删除分块 — KB owner OR Admin+，且对父 KB 有 write 权限\n\t\tchunks.DELETE(\"/:knowledge_id/:id\", g.OwnedChunkKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"knowledge_id\"), handler.DeleteChunk)\n\t\t// 删除知识下的所有分块 — KB owner OR Admin+，且对父 KB 有 write 权限\n\t\tchunks.DELETE(\"/:knowledge_id\", g.OwnedChunkKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"knowledge_id\"), handler.DeleteChunksByKnowledgeID)\n\t\t// 更新分块信息 — KB owner OR Admin+，且对父 KB 有 write 权限\n\t\tchunks.PUT(\"/:knowledge_id/:id\", g.OwnedChunkKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"knowledge_id\"), handler.UpdateChunk)\n\t\tchunks.POST(\"/:knowledge_id/:id/revert\", g.OwnedChunkKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"knowledge_id\"), handler.RevertChunk)\n\t\t// 删除单个生成的问题（通过分块 id） — 与其它 chunk mutation 一致：\n\t\t// KB owner OR Admin+。早期这里因为链路 (chunk_id -> knowledge_id ->\n\t\t// kb -> creator_id) 还没接通，被临时降级成 Contributor，导致一个\n\t\t// 「能编辑所有 chunk 的同样规则在这条路由上反而更宽松」的不一致。\n\t\t// 现在通过 KBCreatorLookupFromChunkIDParam 把那一跳补上，统一矩阵。\n\t\tchunks.DELETE(\"/by-id/:id/questions\", g.OwnedChunkKBOrAdminFromChunkID(), g.KBAccessWriteFromChunkIDParam(\"id\"), handler.DeleteGeneratedQuestion)\n\t\tchunks.PUT(\"/by-id/:id/questions\", g.OwnedChunkKBOrAdminFromChunkID(), g.KBAccessWriteFromChunkIDParam(\"id\"), handler.UpsertGeneratedQuestion)\n\t\tchunks.POST(\"/by-id/:id/questions/regenerate\", g.OwnedChunkKBOrAdminFromChunkID(), g.KBAccessWriteFromChunkIDParam(\"id\"), handler.RegenerateGeneratedQuestions)\n\t}\n}\n\n// RegisterKnowledgeRoutes 注册知识相关的路由\n//\n// Per-KB ownership applies on the per-:id mutating routes (PR 5,\n// #1303): the URL :id is a knowledge id, OwnedKnowledgeKBOrAdmin\n// walks it back to KB.CreatorID so a Contributor who owns the KB can\n// edit/delete any of its documents while a non-owner Contributor gets\n// 403. KB-scoped upload routes (`/knowledge-bases/:id/knowledge/...`)\n// reuse OwnedKBOrAdmin because the URL :id is the KB id directly.\n// Body-scoped batch operations have a Contributor route gate and resolve\n// their KB ownership plus Editor operation grant inside the handler.\nfunc RegisterKnowledgeRoutes(r *gin.RouterGroup, handler *handler.KnowledgeHandler, g *rbacGuards) {\n\t// 知识库下的知识路由组（URL :id is the KB id）。Scoped API key 需要\n\t// ingest 能力才能写内容，且仍受 KB 范围限制；清空 KB 只允许 full-access key。\n\tkb := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id/knowledge\"), apiKeyIngest(apiKeyFullAccess()))\n\tkbRead := kb.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\tkb.POST(\"/file\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.CreateKnowledgeFromFile)\n\t\tkb.POST(\"/url\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.CreateKnowledgeFromURL)\n\t\tkb.POST(\"/manual\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.CreateManualKnowledge)\n\t\tkbRead.GET(\"\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListKnowledge)\n\t\t// 原始文件下载沿用单文件下载的 Contributor + Editor 权限边界。\n\t\tkbRead.POST(\"/batch-download\", g.Contributor(), g.KBAccessWrite(\"id\"), handler.BatchDownloadKnowledge)\n\t\tkbRead.GET(\"/folders\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListKnowledgeFolders)\n\t\tkb.PUT(\"/folders\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.RenameKnowledgeFolder)\n\t\t// Clearing all contents under a KB is a destructive op; gate\n\t\t// behind Admin instead of Contributor.\n\t\tkb.With(apiKeyFullAccess()).DELETE(\"\", g.Admin(), g.KBAccessWrite(\"id\"), handler.ClearKnowledgeBaseContents)\n\t}\n\n\t// Image gallery: list every image asset of a KB (read-only, Viewer+).\n\t// Lives directly under /knowledge-bases/:id so it parallels /knowledge,\n\t// /faq and /tags rather than nesting under /knowledge (documents).\n\tkbImages := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id\"), apiKeyRetrieve(apiKeyFullAccess()))\n\tkbImagesRead := kbImages.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\tkbImagesRead.GET(\"/images\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListImages)\n\t\t// Same listing with the filter as a JSON body: knowledge_ids escapes\n\t\t// the URL-length cap, so the source picker's select-all can name\n\t\t// every document of a large KB.\n\t\tkbImagesRead.POST(\"/images\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListImagesPost)\n\t\t// Self-describing gallery contract: live attribute sources, the\n\t\t// resolved attribute list (definitions + merged usage) and the\n\t\t// caller's search activation state. Per-KB because KB-defined\n\t\t// attribute sources resolve against :id.\n\t\tkbImagesRead.GET(\"/gallery-config\", g.Viewer(), g.KBAccessRead(\"id\"), handler.GetGalleryConfig)\n\t}\n\n\t// Whole-KB index rebuild after an indexing-strategy change (called by the\n\t// KB settings modal via POST /api/v1/knowledge-bases/:id/rebuild-index).\n\t// Content write like /knowledge/batch-reparse: ingest-capable API keys\n\t// may call it; JWT callers need Contributor+ with KB write access, and\n\t// the handler re-validates ownership before enqueueing.\n\tkbRebuild := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id\"), apiKeyIngest(apiKeyFullAccess()))\n\tkbRebuild.POST(\"/rebuild-index\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.RebuildKnowledgeBaseIndex)\n\n\t// 知识路由组（URL :id is a knowledge id; the guard walks it to the parent KB）\n\tkgrp := r.Group(\"/knowledge\")\n\tk := g.apiKeyGroup(kgrp, apiKeyIngest(apiKeyFullAccess()))\n\tkRead := k.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// Cross-knowledge endpoints (no :id) can't be gated on a single\n\t\t// KB via the URL — they accept a kb_id (or source/target KB) in the\n\t\t// body and the handler fans out the access check itself. /batch and\n\t\t// /search are read routes (retrieve). /move, /batch-delete,\n\t\t// /batch-reparse and /tags are content writes that each bound\n\t\t// themselves to a single (or source+target) KB and enforce the API\n\t\t// key's KB allow-list downstream — MoveKnowledge via\n\t\t// requireTenantAPIKeyKnowledgeBases(source,target); the batch ops via\n\t\t// validateKnowledgeBaseAccessWithKBID (requireTenantAPIKeyKnowledgeBase)\n\t\t// plus a per-item \"belongs to the authorized KB\" check in the handler\n\t\t// and service. They are therefore declared for API keys under the\n\t\t// ingest capability, matching their single-document siblings\n\t\t// (k.DELETE(\"/:id\"), k.POST(\"/:id/reparse\"), k.PUT(\"/:id\")).\n\t\tkRead.GET(\"/batch\", g.Viewer(), handler.GetKnowledgeBatch)\n\t\tkRead.GET(\"/:id\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"id\"), handler.GetKnowledge)\n\t\tkRead.GET(\"/:id/stages\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"id\"), handler.GetKnowledgeSpans)\n\t\tkRead.GET(\"/:id/spans\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"id\"), handler.GetKnowledgeSpans)\n\t\tk.DELETE(\"/:id\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.DeleteKnowledge)\n\t\tk.PUT(\"/:id\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.UpdateKnowledge)\n\t\tk.POST(\"/:id/regenerate-summary\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.RegenerateKnowledgeSummary)\n\t\tk.PUT(\"/manual/:id\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.UpdateManualKnowledge)\n\t\tk.POST(\"/:id/reparse\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.ReparseKnowledge)\n\t\tk.POST(\"/:id/cancel-parse\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.CancelKnowledgeParse)\n\t\t// Downloading exposes the original source file, so it has a stricter\n\t\t// boundary than viewing parsed content or previewing it: tenant Viewers\n\t\t// cannot download from their own workspace, and org-shared Viewer access\n\t\t// cannot download from the source workspace. API keys still follow the\n\t\t// retrieve capability declared by kRead; role guards intentionally defer\n\t\t// machine-principal authorization to the API-key gate.\n\t\tkRead.GET(\"/:id/download\", g.Contributor(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.DownloadKnowledgeFile)\n\t\tkRead.GET(\"/:id/preview\", g.Viewer(), g.KBAccessReadFromKnowledgeIDParam(\"id\"), handler.PreviewKnowledgeFile)\n\t\tk.PUT(\"/image/:id/:chunk_id\", g.OwnedKnowledgeKBOrAdmin(), g.KBAccessWriteFromKnowledgeIDParam(\"id\"), handler.UpdateImageInfo)\n\t\tkRead.GET(\"/search\", g.Viewer(), handler.SearchKnowledge)\n\t\tkRead.GET(\"/move/progress/:task_id\", g.Viewer(), handler.GetKnowledgeMoveProgress)\n\t\t// Batch / cross-KB content writes: JWT Contributor+, or an API key\n\t\t// with the ingest capability (or full access). Each handler binds the\n\t\t// operation to a single (move: source+target) KB and rejects any KB\n\t\t// or knowledge id outside the key's allow-list, so a scoped ingest key\n\t\t// can only touch KBs it is already permitted to write.\n\t\tk.PUT(\"/tags\", g.Contributor(), handler.UpdateKnowledgeTagBatch)\n\t\tk.POST(\"/batch-reparse\", g.Contributor(), handler.BatchReparseKnowledge)\n\t\tk.POST(\"/batch-delete\", g.Contributor(), handler.BatchDeleteKnowledge)\n\t\tk.POST(\"/folder\", g.Contributor(), handler.MoveKnowledgeToFolder)\n\t\tk.POST(\"/move\", g.Contributor(), handler.MoveKnowledge)\n\t}\n}\n\n// RegisterFAQRoutes 注册 FAQ 相关路由\n//\n// FAQ entries are KB content: reads are Viewer+, all mutations\n// (create / update / upsert / delete / batch field+tag updates,\n// import display flag) are Contributor+. Search is read-only.\nfunc RegisterFAQRoutes(r *gin.RouterGroup, handler *handler.FAQHandler, g *rbacGuards) {\n\tif handler == nil {\n\t\treturn\n\t}\n\t// FAQ entries 是 KB 的子资源（FAQ-type KB 的内容主体）。修改 FAQ\n\t// 等价于修改 KB 内容，必须遵循 KB 的\"creator OR Admin+\"矩阵 ——\n\t// 跟 chunks / wiki pages 保持一致。Viewer+ 可以读，Contributor 不能\n\t// 改不属于自己的 KB 的 FAQ。\n\tfaq := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id/faq\"), apiKeyIngest(apiKeyFullAccess()))\n\tfaqRead := faq.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// KBAccessRead/Write resolve own/shared/agent-visible access and\n\t\t// rewrite the request's tenant context — handler no longer\n\t\t// carries an effectiveCtxForKB helper.\n\t\tfaqRead.GET(\"/entries\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListEntries)\n\t\tfaqRead.GET(\"/entries/export\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ExportEntries)\n\t\tfaqRead.GET(\"/entries/:entry_id\", g.Viewer(), g.KBAccessRead(\"id\"), handler.GetEntry)\n\t\tfaq.POST(\"/entries\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpsertEntries)\n\t\tfaq.PATCH(\"/entries\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.PatchEntriesBatch)\n\t\tfaq.POST(\"/entry\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.CreateEntry)\n\t\tfaq.PUT(\"/entries/:entry_id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateEntry)\n\t\tfaq.POST(\"/entries/:entry_id/similar-questions\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.AddSimilarQuestions)\n\t\t// Unified batch update API - supports is_enabled, is_recommended, tag_id\n\t\tfaq.PUT(\"/entries/fields\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateEntryFieldsBatch)\n\t\tfaq.PUT(\"/entries/tags\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateEntryTagBatch)\n\t\tfaq.DELETE(\"/entries\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.DeleteEntries)\n\t\t// Search is a read route: scoped API keys may call it with retrieve\n\t\t// even though POST is otherwise an unsafe method.\n\t\tfaqRead.POST(\"/search\", g.Viewer(), g.KBAccessRead(\"id\"), handler.SearchFAQ)\n\t\t// FAQ import result display status\n\t\tfaq.PUT(\"/import/last-result/display\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateLastImportResultDisplayStatus)\n\t}\n\t// FAQ import progress route (outside of knowledge-base scope) — Viewer+.\n\t// Scoped API keys that can ingest (they start the import) or retrieve may\n\t// poll their own import/dry-run progress. The task is tenant-scoped by\n\t// requireTaskProgressTenant, so a key only ever sees its own tenant's\n\t// tasks. Declared through apiKeyRoute so the APIKeyGate doesn't fail-closed\n\t// and 403 the poller with \"scope does not allow this operation\".\n\tg.apiKeyRoute(r, http.MethodGet, \"/faq/import/progress/:task_id\",\n\t\tapiKeyRetrieve(apiKeyIngest(apiKeyFullAccess())), g.Viewer(), handler.GetImportProgress)\n}\n\n// RegisterKnowledgeBaseRoutes 注册知识库相关的路由\nfunc RegisterKnowledgeBaseRoutes(r *gin.RouterGroup, handler *handler.KnowledgeBaseHandler, g *rbacGuards) {\n\t// 知识库路由组。API-key 可达性按能力分两档，全部通过 apiKeyGroup 声明，\n\t// 不要再用裸 kbgrp.Handle 注册（那会绕过网关、对所有 key 静默默认拒绝）：\n\t//\n\t//   1. 读取（list/detail/search/progress/move-targets）—— retrieve OR full-access（kb）\n\t//   2. KB 生命周期管理（create/copy/duplicate/update/delete）\n\t//      —— manage_kbs OR full-access（kbManagement）\n\t//\n\t// 第 2 档整条 KB 生命周期共用同一策略：manage_kbs 是「管理知识库」capability，\n\t// 建/拷/改/删都是它的分内事。KB 的 allow-list 仍在下游生效——copy/duplicate/\n\t// update/delete 的目标 KB 会被 allow-list 兜住；create 无源可约束，限定 allow-list\n\t// 的 key 建出的新 KB 落在其 allow-list 之外（同租户、无越权，只是建完自己管不到），\n\t// 空 allow-list 的 key 则是全租户 KB 管理、新建天然在范围内。KB 内容写入（文档/\n\t// 分块/FAQ/Tag/Wiki）由对应子路由的 ingest 能力控制，不在本组。\n\tkbgrp := r.Group(\"/knowledge-bases\")\n\tkb := g.apiKeyGroup(kbgrp, apiKeyRetrieve(apiKeyFullAccess()))\n\tkbManagement := kb.With(apiKeyManageKnowledgeBases(apiKeyFullAccess()))\n\t{\n\t\t// 创建知识库 — JWT Contributor+；API key 需 manage_kbs 或 full-access。\n\t\tkbManagement.POST(\"\", g.Contributor(), handler.CreateKnowledgeBase)\n\t\t// 获取知识库列表 — Viewer+ for JWT callers; retrieve-capable API keys pass via the gate.\n\t\tkb.GET(\"\", g.Viewer(), handler.ListKnowledgeBases)\n\t\t// 获取知识库详情 — Viewer+ 且对 KB 有 read 权限\n\t\tkb.GET(\"/:id\", g.Viewer(), g.KBAccessRead(\"id\"), handler.GetKnowledgeBase)\n\t\t// 更新/删除知识库 — 两层正交鉴权，缺一不可：\n\t\t//   OwnedKBOrAdmin  管「租户内」归属：非创建者的 Contributor 改不了\n\t\t//                   同事的 KB（跨租户 KB 在此走 lookup=NotFound → 交给\n\t\t//                   下游处理，不在此拦）。\n\t\t//   KBAccessWrite   管「跨租户」访问级：自有 KB 或被组织共享(editor)。\n\t\t// handler 内再按 permission/所有者租户做最终判定 —— 尤其 DeleteKnowledgeBase\n\t\t// 以调用者「自身」租户(c.Keys，未被 KBAccess 改写)校验 kb.TenantID，\n\t\t// 把删除锁死为「所有者租户 + Admin」，共享 editor 无法删除源 KB。\n\t\tkbManagement.PUT(\"/:id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.UpdateKnowledgeBase)\n\t\tkbManagement.PATCH(\"/:id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.PatchKnowledgeBase)\n\t\t// 立即重新生成知识库 AI 描述 — 与更新知识库同档鉴权；同步执行一次小模型调用。\n\t\tkbManagement.POST(\"/:id/profile/generate\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"),\n\t\t\thandler.GenerateKnowledgeBaseProfile)\n\t\tkbManagement.DELETE(\"/:id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), handler.DeleteKnowledgeBase)\n\t\t// 置顶/取消置顶知识库 — 创建者本人 OR Admin+ 且对 KB 有 write 权限\n\t\t// Pin state is now per-(user, kb) (migration 000050). Anyone with\n\t\t// at least Viewer-level read access to the KB — including users\n\t\t// who reached it via a shared agent — may pin it for themselves;\n\t\t// no edit permission is required. The OwnedKBOrAdmin guard was\n\t\t// removed accordingly. The route still requires KB read access\n\t\t// so callers can't poke at KBs they can't see.\n\t\tkb.PUT(\"/:id/pin\", g.Viewer(), g.KBAccessRead(\"id\"), handler.TogglePinKnowledgeBase)\n\t\t// 混合搜索 — Viewer+ 且对 KB 有 read 权限 (read-only)\n\t\t// POST is preferred; GET with JSON body is kept for backward compatibility (#1727).\n\t\tkb.POST(\"/:id/hybrid-search\", g.Viewer(), g.KBAccessRead(\"id\"), handler.HybridSearch)\n\t\tkb.GET(\"/:id/hybrid-search\", g.Viewer(), g.KBAccessRead(\"id\"), handler.HybridSearch)\n\t\t// 拷贝知识库 — 产出新 KB，与 create 同档：JWT Contributor+，API key 需 manage_kbs 或 full-access。\n\t\t// 源 KB 通过 body 里的 source_id 传入（非 :id 路径参数），无法套用基于路径参数\n\t\t// 的 KBAccessRead，故源/目标 KB 的租户归属与 allow-list 校验在 handler 内完成\n\t\t// （requireTenantAPIKeyKnowledgeBases 会把 source_id/target_id 兜进 allow-list）。\n\t\t// 副本归调用者所有，不需要原 KB 的所有权。\n\t\tkbManagement.POST(\"/copy\", g.Contributor(), handler.CopyKnowledgeBase)\n\t\t// 创建知识库副本 — 产出新 KB，与 create 同档：JWT Contributor+，API key 需 manage_kbs 或 full-access；\n\t\t// 且对源 KB 有 read 权限（KBAccessRead 会对限定 key 兜住源 KB）。只创建新的 KB 设置记录，不复制内容/索引/分享。\n\t\tkbManagement.POST(\"/:id/duplicate\", g.Contributor(), g.KBAccessRead(\"id\"), handler.DuplicateKnowledgeBase)\n\t\t// 获取知识库复制进度 — Viewer+；只读。manage_kbs（发起 copy 的 key）或\n\t\t// retrieve 均可轮询；任务按租户隔离（requireTaskProgressTenant），key 只能\n\t\t// 查本租户任务。\n\t\tkb.With(apiKeyRetrieve(apiKeyManageKnowledgeBases(apiKeyFullAccess()))).\n\t\t\tGET(\"/copy/progress/:task_id\", g.Viewer(), handler.GetKBCloneProgress)\n\t\t// 获取可移动目标知识库列表 — Viewer+ 且对 KB 有 read 权限\n\t\tkb.GET(\"/:id/move-targets\", g.Viewer(), g.KBAccessRead(\"id\"), handler.ListMoveTargets)\n\t}\n}\n\n// RegisterImageAttrRoutes wires the global, read-only image-attribute registry\n// that drives the KB editor's attribute panel.\n//\n// The registry is a single source of truth, so adding an attribute is a\n// backend-only change (one registry row) and the UI follows automatically. It\n// carries no KB id and needs only the Viewer role, so — like the other\n// read-only KB-editor helpers GET /chunker/preview and GET\n// /system/parser-engines — it is mounted at the top level rather than under\n// the /knowledge-bases collection.\nfunc RegisterImageAttrRoutes(r *gin.RouterGroup, handler *handler.KnowledgeBaseHandler, g *rbacGuards) {\n\tg.apiKeyRoute(r, http.MethodGet, \"/image-attrs/schema\",\n\t\tapiKeyRetrieve(apiKeyFullAccess()), g.Viewer(), handler.GetImageAttrsSchema)\n\t// Same shape and the same audience as the schema above: a read-only list of\n\t// what the settings panel can offer, with no KB id, so the Viewer role is\n\t// enough. Mounted here rather than under /knowledge-bases because neither\n\t// the list nor a pipeline id is knowledge-base-specific.\n\tg.apiKeyRoute(r, http.MethodGet, \"/image-pipelines\",\n\t\tapiKeyRetrieve(apiKeyFullAccess()), g.Viewer(), handler.GetImagePipelines)\n\t// The settings panel asks this while the user edits, so that a combination\n\t// the pipeline cannot run is pointed out before the save rather than\n\t// rejected by it. Read-only, global, and answered from the pipeline's own\n\t// rules, so only the Viewer role is required.\n\tg.apiKeyRoute(r, http.MethodPost, \"/image-pipelines/validate\",\n\t\tapiKeyRetrieve(apiKeyFullAccess()), g.Viewer(), handler.ValidateImagePipelines)\n}\n\n// RegisterKnowledgeBaseActivityRoutes exposes the read-only per-KB activity\n// feed. It intentionally stays JWT-only: audit history is a sensitive owner\n// surface and no existing workspace API-key capability grants audit access.\nfunc RegisterKnowledgeBaseActivityRoutes(r *gin.RouterGroup, auditHandler *handler.AuditLogHandler, g *rbacGuards) {\n\tif auditHandler == nil {\n\t\treturn\n\t}\n\tr.GET(\"/knowledge-bases/:id/activity\",\n\t\tg.OwnedKBOrAdmin(), g.KBAccessRead(\"id\"), auditHandler.ListKnowledgeBaseActivity)\n}\n\n// RegisterKnowledgeTagRoutes 注册知识库标签相关路由。\n//\n// Tags are KB metadata: Viewer reads, Contributor writes. Per-KB\n// ownership granularity for tags is out of scope for PR 2; this is\n// purely role-based.\nfunc RegisterKnowledgeTagRoutes(r *gin.RouterGroup, tagHandler *handler.TagHandler, g *rbacGuards) {\n\tif tagHandler == nil {\n\t\treturn\n\t}\n\t// Tags 是 KB 的子资源 — 创建/编辑/删除标签会改变 KB 内容的检索分类\n\t// 行为，应该与 KB 主体的\"creator OR Admin+\"矩阵一致，避免一个无\n\t// 关 Contributor 在他人 KB 里乱建/删标签影响 KB owner 的内容组织。\n\tkbTags := g.apiKeyGroup(r.Group(\"/knowledge-bases/:id/tags\"), apiKeyIngest(apiKeyFullAccess()))\n\tkbTagsRead := kbTags.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// KBAccessRead/Write resolve own/shared/agent-visible access and\n\t\t// rewrite the request's tenant context to the effective tenant\n\t\t// for the duration of the handler — so the handler no longer\n\t\t// needs its own effectiveCtxForKB helper.\n\t\tkbTagsRead.GET(\"\", g.Viewer(), g.KBAccessRead(\"id\"), tagHandler.ListTags)\n\t\tkbTags.POST(\"\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), tagHandler.CreateTag)\n\t\tkbTags.PUT(\"/:tag_id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), tagHandler.UpdateTag)\n\t\tkbTags.DELETE(\"/:tag_id\", g.OwnedKBOrAdmin(), g.KBAccessWrite(\"id\"), tagHandler.DeleteTag)\n\t}\n}\n\n// RegisterWikiPageRoutes registers wiki page related routes.\n//\n// Wiki pages are KB content (wiki mode): reads are Viewer+ and gated by\n// KBAccessRead (own / org-shared / via shared agent), matching FAQ /\n// chunk / tag read routes. Content mutations (create/update/delete) and\n// maintenance actions (rebuild-links, auto-fix, change issue status)\n// honour per-KB ownership via OwnedWikiKBOrAdmin (PR 5, #1303): the URL\n// :kb_id resolves directly to the owning KB so a Contributor who owns\n// the KB can manage its wiki, while a non-owner Contributor gets 403.\nfunc RegisterWikiPageRoutes(r *gin.RouterGroup, wikiHandler *handler.WikiPageHandler, g *rbacGuards) {\n\twiki := g.apiKeyGroup(r.Group(\"/knowledgebase/:kb_id/wiki\"), apiKeyIngest(apiKeyFullAccess()))\n\twikiRead := wiki.With(apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\t// Page CRUD\n\t\twikiRead.GET(\"/pages\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.ListPages)\n\t\twiki.POST(\"/pages\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.CreatePage)\n\t\twiki.PUT(\"/move-page\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.MovePage)\n\t\twikiRead.GET(\"/pages/*slug\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.GetPage)\n\t\twiki.PUT(\"/pages/*slug\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.UpdatePage)\n\t\twiki.DELETE(\"/pages/*slug\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.DeletePage)\n\n\t\t// Revision history (slug is a catch-all like /pages; revert carries\n\t\t// the slug in the body for the same reason move-page does)\n\t\twikiRead.GET(\"/revisions/*slug\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.ListRevisions)\n\t\twiki.POST(\"/revert\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.RevertPage)\n\n\t\t// Folder tree (directory nodes)\n\t\twikiRead.GET(\"/folders\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.ListFolders)\n\t\twiki.POST(\"/folders\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.CreateFolder)\n\t\twiki.PUT(\"/folders/:folder_id\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.UpdateFolder)\n\t\twiki.DELETE(\"/folders/:folder_id\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.DeleteFolder)\n\n\t\t// Special pages\n\t\twikiRead.GET(\"/index\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.GetIndex)\n\n\t\t// Graph and stats\n\t\twikiRead.GET(\"/graph\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.GetGraph)\n\t\twikiRead.GET(\"/stats\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.GetStats)\n\n\t\t// Search and maintenance\n\t\twikiRead.GET(\"/search\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.SearchPages)\n\t\twiki.POST(\"/rebuild-links\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.RebuildLinks)\n\t\twikiRead.GET(\"/lint\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.Lint)\n\t\twiki.POST(\"/auto-fix\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.AutoFix)\n\n\t\t// Issues\n\t\twikiRead.GET(\"/issues\", g.Viewer(), g.KBAccessRead(\"kb_id\"), wikiHandler.ListIssues)\n\t\twiki.PUT(\"/issues/:issue_id/status\", g.OwnedWikiKBOrAdmin(), g.KBAccessWrite(\"kb_id\"), wikiHandler.UpdateIssueStatus)\n\t}\n\n\twikiSearch := g.apiKeyGroup(r.Group(\"/wiki-search\", g.Viewer()), apiKeyRetrieve(apiKeyFullAccess()))\n\t{\n\t\twikiSearch.POST(\"\", wikiHandler.SearchPagesAcross)\n\t}\n}\n"
    },
    {
      "path": "internal/application/service/knowledgebase_search.go",
      "content": "package service\n\nimport (\n\t\"context\"\n\t\"fmt\"\n\n\t\"github.com/Tencent/WeKnora/internal/application/service/retriever\"\n\tapperrors \"github.com/Tencent/WeKnora/internal/errors\"\n\t\"github.com/Tencent/WeKnora/internal/logger\"\n\t\"github.com/Tencent/WeKnora/internal/models/embedding\"\n\t\"github.com/Tencent/WeKnora/internal/tracing/langfuse\"\n\t\"github.com/Tencent/WeKnora/internal/types\"\n\tsecutils \"github.com/Tencent/WeKnora/internal/utils\"\n)\n\n// maxRetrievalPoolSize bounds every retrieval depth derived from MatchCount:\n// the over-retrieval pool below and the doubling TopK of the FAQ iterative\n// path. Without it a caller-supplied MatchCount scales the vector-store query\n// depth without limit.\nconst maxRetrievalPoolSize = 500\n\n// GetQueryEmbedding computes the query embedding using the embedding model\n// associated with the given knowledge base. Callers can pre-compute and reuse\n// the result across multiple KBs that share the same embedding model and\n// configured vector dimension to avoid redundant embedding API calls.\nfunc (s *knowledgeBaseService) GetQueryEmbedding(ctx context.Context, kbID string, queryText string) ([]float32, error) {\n\tkb, err := s.repo.GetKnowledgeBaseByID(ctx, kbID)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\n\tcurrentTenantID := types.MustTenantIDFromContext(ctx)\n\tvar embeddingModel embedding.Embedder\n\n\tif kb.TenantID != currentTenantID {\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModelForTenant(ctx, kb.EmbeddingModelID, kb.TenantID)\n\t} else {\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModel(ctx, kb.EmbeddingModelID)\n\t}\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"GetQueryEmbedding: failed to get embedding model %s: %v\", kb.EmbeddingModelID, err)\n\t\treturn nil, err\n\t}\n\n\tvector, err := embeddingModel.Embed(types.WithEmbedQuery(ctx), queryText)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif err := validateQueryEmbeddingDimension(embeddingModel, len(vector)); err != nil {\n\t\tlogger.Errorf(ctx, \"GetQueryEmbedding: %v\", err)\n\t\treturn nil, err\n\t}\n\treturn vector, nil\n}\n\n// validateQueryEmbeddingDimension catches provider/model configuration drift\n// before a malformed query reaches the vector store. Without this check, a\n// provider returning a different vector size is reported as the misleading\n// generic 2201 \"bound store unavailable\" error (or, for dimension-partitioned\n// stores, silently produces no matches).\nfunc validateQueryEmbeddingDimension(model embedding.Embedder, actual int) error {\n\tif model == nil || actual == 0 {\n\t\treturn nil\n\t}\n\texpected := model.GetDimensions()\n\tif expected <= 0 || expected == actual {\n\t\treturn nil\n\t}\n\treturn apperrors.NewVectorStoreUnavailableError(\n\t\t\"embedding vector dimension does not match the configured model\",\n\t).WithDetails(map[string]any{\n\t\t\"model\":              model.GetModelName(),\n\t\t\"expected_dimension\": expected,\n\t\t\"actual_dimension\":   actual,\n\t\t\"hint\":               fmt.Sprintf(\"check the embedding model configuration and rebuild the affected index (%d dimensions)\", expected),\n\t})\n}\n\n// ResolveEmbeddingModelKeys resolves embedding model IDs to their actual model\n// identity key (name + endpoint + configured vector dimension). KBs using the\n// same underlying model and vector space across different tenants will share\n// the same key, enabling optimal grouping without reusing a query embedding\n// across incompatible index dimensions.\nfunc (s *knowledgeBaseService) ResolveEmbeddingModelKeys(ctx context.Context, kbs []*types.KnowledgeBase) map[string]string {\n\ttype modelRef struct {\n\t\tModelID  string\n\t\tTenantID uint64\n\t}\n\n\t// Deduplicate model references\n\tuniqueRefs := make(map[modelRef]struct{})\n\tkbRefs := make(map[string]modelRef, len(kbs))\n\tfor _, kb := range kbs {\n\t\tref := modelRef{ModelID: kb.EmbeddingModelID, TenantID: kb.TenantID}\n\t\tuniqueRefs[ref] = struct{}{}\n\t\tkbRefs[kb.ID] = ref\n\t}\n\n\t// Resolve each unique (modelID, tenantID) to a model identity key. The\n\t// configured dimension is part of the key because providers such as OpenAI\n\t// support multiple output widths for one model name and endpoint.\n\tresolvedKeys := make(map[modelRef]string, len(uniqueRefs))\n\tfor ref := range uniqueRefs {\n\t\ttenantCtx := types.WithExecutionTenant(ctx, ref.TenantID)\n\t\tmodel, err := s.modelService.GetModelByID(tenantCtx, ref.ModelID)\n\t\tif err != nil || model == nil {\n\t\t\tlogger.Warnf(ctx, \"ResolveEmbeddingModelKeys: cannot resolve model %s for tenant %d: %v\", ref.ModelID, ref.TenantID, err)\n\t\t\tresolvedKeys[ref] = ref.ModelID\n\t\t\tcontinue\n\t\t}\n\t\tresolvedKeys[ref] = fmt.Sprintf(\"%s|%s|%d\", model.Name, model.Parameters.BaseURL,\n\t\t\tmodel.Parameters.EmbeddingParameters.Dimension)\n\t}\n\n\tresult := make(map[string]string, len(kbs))\n\tfor _, kb := range kbs {\n\t\tresult[kb.ID] = resolvedKeys[kbRefs[kb.ID]]\n\t}\n\treturn result\n}\n\n// HybridSearch performs hybrid search, including vector retrieval and keyword retrieval.\n//\n// id is the \"primary\" knowledge base ID used to resolve the embedding model and\n// determine the KB type (e.g. FAQ). When params.KnowledgeBaseIDs is set, those\n// IDs are used for the actual retrieval scope instead of id alone, allowing a\n// single call to span multiple KBs that share the same embedding model. In that\n// case id should be any one of those KBs (typically the first) so that its\n// embedding model and type configuration are used for the search.\nfunc (s *knowledgeBaseService) HybridSearch(ctx context.Context,\n\tid string,\n\tparams types.SearchParams,\n) ([]*types.SearchResult, error) {\n\t// Normalize once, before anything reads MatchCount. params is a value\n\t// copy, so this stays local to the call.\n\tparams.MatchCount = normalizedMatchCount(params.MatchCount)\n\n\tchunks, err := s.hybridSearchCandidates(ctx, id, params)\n\tif err != nil || len(chunks) == 0 {\n\t\treturn nil, err\n\t}\n\n\trecordImageRecallDecision(ctx, \"fusion.candidate_selection\", \"\",\n\t\tsummarizeImageCandidateCut(chunks, params.MatchCount))\n\n\t// Truncate to the primary-match cap. MatchCount is guaranteed positive by\n\t// the normalization at the top of this function; the slice bound below\n\t// depends on that.\n\tif len(chunks) > params.MatchCount {\n\t\tchunks = chunks[:params.MatchCount]\n\t}\n\n\treturn s.processSearchResults(ctx, chunks, params.SkipContextEnrichment)\n}\n\n// hybridSearchCandidates runs retrieval, fusion and FAQ post-processing for\n// HybridSearch and returns the fused chunks, best first, before the\n// MatchCount cut. params.MatchCount must already be normalized.\nfunc (s *knowledgeBaseService) hybridSearchCandidates(ctx context.Context,\n\tid string,\n\tparams types.SearchParams,\n) ([]*types.IndexWithScore, error) {\n\t// Determine the set of KB IDs to search.\n\tsearchKBIDs := params.KnowledgeBaseIDs\n\tif len(searchKBIDs) == 0 {\n\t\tsearchKBIDs = []string{id}\n\t}\n\n\t// QueryText is user-controlled; sanitize before logging to prevent\n\t// CR/LF/tab log injection. Matches the handler-layer sanitization at\n\t// handler/knowledgebase.go.\n\tlogger.Infof(ctx, \"Hybrid search parameters, knowledge base IDs: %v, query text: %s\",\n\t\tsearchKBIDs, secutils.SanitizeForLog(params.QueryText))\n\n\ttenantInfo, _ := types.TenantInfoFromContext(ctx)\n\n\t// Batch-load every KB in scope. Required for store grouping,\n\t// embedding-model consistency validation, and FAQ type detection.\n\t// GetKnowledgeBaseByIDs is intentionally tenant-agnostic at the\n\t// repository layer so that Organization-shared KBs (owned by a\n\t// different tenant) can be loaded here; authorization for each\n\t// returned row is enforced explicitly below.\n\tkbs, err := s.repo.GetKnowledgeBaseByIDs(ctx, searchKBIDs)\n\tif err != nil {\n\t\tlogger.ErrorWithFields(ctx, err, map[string]interface{}{\n\t\t\t\"knowledge_base_ids\": searchKBIDs,\n\t\t})\n\t\treturn nil, err\n\t}\n\tif len(kbs) == 0 {\n\t\treturn nil, apperrors.NewNotFoundError(\"knowledge base not found\")\n\t}\n\n\t// Authorize every KB for the original caller, using exact upstream\n\t// grants or organization permissions. Execution in a shared tenant\n\t// does not grant access to its other KBs. Without this guard, a\n\t// caller could pass arbitrary KB UUIDs in params.KnowledgeBaseIDs\n\t// and reach foreign tenants' bound vector stores via the per-group\n\t// engine resolution downstream.\n\tif err := s.authorizeKBAccess(ctx, kbs); err != nil {\n\t\treturn nil, err\n\t}\n\n\t// Explicit embedding-model consistency check. Multi-KB searches that\n\t// span different embedding spaces would otherwise silently produce\n\t// meaningless cross-model scores. Same-model wiki/graph KBs are\n\t// tolerated — see validateSameEmbeddingModel for the carve-out.\n\tif err := s.validateSameEmbeddingModel(ctx, kbs); err != nil {\n\t\treturn nil, err\n\t}\n\n\t// Resolve the primary KB — embedding model + FAQ type come from this\n\t// one. Miss → 404 (no kbs[0] fallback; a silent pivot to an arbitrary\n\t// KB would hide caller bugs and reveal foreign KB metadata).\n\tkb := pickPrimary(kbs, id)\n\tif kb == nil {\n\t\treturn nil, apperrors.NewNotFoundError(\"knowledge base not found\")\n\t}\n\n\t// Over-retrieval (existing rule, preserved): 5x per-KB matchCount,\n\t// floored at DefaultRetrievalTopK, capped at maxRetrievalPoolSize across\n\t// the whole search.\n\tmatchCount := max(params.MatchCount*5, types.DefaultRetrievalTopK) * len(searchKBIDs)\n\tif matchCount > maxRetrievalPoolSize {\n\t\tmatchCount = maxRetrievalPoolSize\n\t}\n\n\t// Compute the query embedding once before fan-out and propagate via\n\t// params.QueryEmbedding. Without this, each storeGroup's\n\t// buildRetrievalParams would re-embed the same query text — for N\n\t// stores that means N API calls of identical input.\n\t//\n\t// Skip when params already carries an embedding (e.g. the agent\n\t// pre-computed it) or when the primary KB has no vector indexing\n\t// configured.\n\tembeddingKB := kb\n\tif !hasEmbeddingModel(embeddingKB) {\n\t\tembeddingKB = nil\n\t\tfor _, candidate := range kbs {\n\t\t\tif hasEmbeddingModel(candidate) {\n\t\t\t\tembeddingKB = candidate\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t}\n\tif len(params.QueryEmbedding) == 0 && embeddingKB != nil && !params.DisableVectorMatch {\n\t\temb, embErr := s.GetQueryEmbedding(ctx, embeddingKB.ID, params.QueryText)\n\t\tif embErr != nil {\n\t\t\treturn nil, embErr\n\t\t}\n\t\tparams.QueryEmbedding = emb\n\t}\n\n\t// Group KBs by (storeID, owner tenant), resolve the bound engine for\n\t// each group, and build the per-group base RetrieveParams once.\n\tgroups, err := s.resolveStoreGroups(ctx, kb, kbs, params, matchCount)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif len(groups) == 0 || allBaseParamsEmpty(groups) {\n\t\t// Wiki-only / graph-only fan-out: every KB is non-retrievable.\n\t\t// Preserve the existing \"return empty rather than error\" contract\n\t\t// so agent tools that combine multiple KB scopes degrade gracefully.\n\t\tlogger.Infof(ctx, \"No retrievable indexing pipelines across %d KBs\", len(kbs))\n\t\treturn nil, nil\n\t}\n\n\t// Image vectors are recalled only for KBs that opted in to them.\n\ts.applyImageRecall(ctx, kbs, groups, params)\n\n\t// Execute retrieval with fan-out + score normalization (multi-store\n\t// only) and a langfuse span around the entire retrieve step.\n\tlogger.Infof(ctx, \"Starting multi-store retrieval, group count: %d\", len(groups))\n\tretrieveCtx, retrieveSpan := langfuse.GetManager().StartSpan(ctx, langfuse.SpanOptions{\n\t\tName: \"retrieve\",\n\t\tInput: map[string]interface{}{\n\t\t\t\"query_text\":             params.QueryText,\n\t\t\t\"kb_ids\":                 searchKBIDs,\n\t\t\t\"knowledge_ids\":          params.KnowledgeIDs,\n\t\t\t\"tag_ids\":                params.TagIDs,\n\t\t\t\"scope_tag_ids\":          params.ScopeTagIDs,\n\t\t\t\"match_count\":            matchCount,\n\t\t\t\"vector_threshold\":       params.VectorThreshold,\n\t\t\t\"keyword_threshold\":      params.KeywordThreshold,\n\t\t\t\"disable_vector_match\":   params.DisableVectorMatch,\n\t\t\t\"disable_keywords_match\": params.DisableKeywordsMatch,\n\t\t\t\"group_count\":            len(groups),\n\t\t},\n\t\tMetadata: map[string]interface{}{\n\t\t\t\"primary_kb_id\":       kb.ID,\n\t\t\t\"primary_kb_type\":     string(kb.Type),\n\t\t\t\"embedding_model_id\":  kb.EmbeddingModelID,\n\t\t\t\"has_query_embedding\": len(params.QueryEmbedding) > 0,\n\t\t},\n\t})\n\tretrieveResults, err := s.retrieveFromStores(retrieveCtx, groups, retriever.EngineAwareNormalizer{})\n\tretrieveSpan.Finish(langfuse.SummarizeRetrieveOutput(retrieveResults), nil, err)\n\tif err != nil {\n\t\tlogger.ErrorWithFields(ctx, err, map[string]interface{}{\n\t\t\t\"knowledge_base_ids\": searchKBIDs,\n\t\t\t\"query_text\":         params.QueryText,\n\t\t})\n\t\treturn nil, err\n\t}\n\n\t// Separate and fuse retrieval results.\n\tvectorLists, keywordLists := classifyRetrievalResults(ctx, retrieveResults)\n\tvectorResults, keywordResults := flattenLists(vectorLists), flattenLists(keywordLists)\n\tif len(vectorResults) == 0 && len(keywordResults) == 0 {\n\t\tlogger.Info(ctx, \"No search results found\")\n\t\treturn nil, nil\n\t}\n\tlogger.Infof(ctx, \"Result count before fusion: vector=%d, keyword=%d\",\n\t\tlen(vectorResults), len(keywordResults))\n\n\tvar retrievalCfg *types.RetrievalConfig\n\tif tenantInfo != nil {\n\t\tretrievalCfg = tenantInfo.RetrievalConfig\n\t}\n\tdeduplicatedChunks := fuseOrDeduplicate(ctx, vectorLists, keywordLists, retrievalCfg)\n\n\tkb.EnsureDefaults()\n\n\t// FAQ-specific post-processing now operates on storeGroups so the\n\t// iterative TopK growth applies uniformly across the fan-out. An\n\t// AppError from inside the iterative fan-out path (e.g. a per-group\n\t// timeout surfaced as ErrVectorStoreUnavailable) must surface to the\n\t// caller rather than be silently converted to a truncated chunk list.\n\treturn s.applyFAQPostProcessing(\n\t\tctx, kb, kbs, deduplicatedChunks, vectorLists, groups, params, matchCount)\n}\n\n// normalizedMatchCount resolves the effective primary-match cap for a search.\n//\n// MatchCount arrives as Go's zero value whenever a caller omits it — JSON\n// cannot tell an absent match_count from an explicit 0 — and three consumers\n// inside HybridSearch read it: the over-retrieval floor, the FAQ\n// iterative-retrieval trigger, and the final truncation. They must agree, so\n// the value is resolved here rather than at each use site. A raw 0 truncates\n// the deduplicated chunk list to [:0] and empties an otherwise successful\n// search; a negative value panics on that same slice bound.\n//\n// The fallback is shared with RetrievalConfig.GetEffectiveEmbeddingTopK:\n// internal callers (chat pipeline, agent tools) feed these results into\n// reranking, which trims to RerankTopK afterwards, so a wide candidate pool is\n// the right failure mode for them.\nfunc normalizedMatchCount(requested int) int {\n\tif requested <= 0 {\n\t\treturn types.DefaultRetrievalTopK\n\t}\n\t// A search never returns more than the pool it draws from, so capping here\n\t// changes no result; it keeps the over-retrieval arithmetic\n\t// (MatchCount*5*len(KBs), the FAQ path's MatchCount*3) from overflowing\n\t// into a negative TopK on absurd input.\n\treturn min(requested, maxRetrievalPoolSize)\n}\n\n// hasEmbeddingModel reports whether kb is vector-indexed with a configured\n// embedding model, i.e. whether it can embed a query for vector retrieval.\nfunc hasEmbeddingModel(kb *types.KnowledgeBase) bool {\n\treturn kb != nil && kb.IsVectorEnabled() && kb.EmbeddingModelID != \"\"\n}\n\n// pickPrimary returns the KB whose ID matches id, or nil if id is not in\n// scope. Callers map a nil result to NotFound; there is intentionally no\n// kbs[0] fallback because it would mask caller bugs and could leak an\n// unintended KB's embedding-model identity into the search path.\n//\n// The primary KB drives the embedding model and FAQ-type decisions for\n// buildRetrievalParams. If the caller selects a wiki-only / graph-only\n// KB as primary, the multi-KB search is implicitly demoted to\n// keyword-only retrieval — vector retrieval is skipped because\n// primary.IsVectorEnabled() is false. Callers that mix vector-enabled\n// and non-vector KBs should pass a vector-enabled KB as id.\nfunc pickPrimary(kbs []*types.KnowledgeBase, id string) *types.KnowledgeBase {\n\tfor _, kb := range kbs {\n\t\tif kb.ID == id {\n\t\t\treturn kb\n\t\t}\n\t}\n\treturn nil\n}\n\n// allBaseParamsEmpty reports whether every store group has an empty\n// BaseParams slice. True only when every KB in scope is wiki-only or\n// graph-only with neither vector nor keyword indexing — HybridSearch then\n// returns nil so callers that combine searchable + non-searchable KBs\n// (agent tools, chat pipeline) degrade gracefully.\nfunc allBaseParamsEmpty(groups []*storeGroup) bool {\n\tfor _, g := range groups {\n\t\tif len(g.BaseParams) > 0 {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// totalHits counts the IndexWithScore entries across a slice of retrieve\n// results.\nfunc totalHits(rrs []*types.RetrieveResult) int {\n\tn := 0\n\tfor _, r := range rrs {\n\t\tn += len(r.Results)\n\t}\n\treturn n\n}\n\n// buildRetrievalParams constructs the vector and keyword retrieval parameters\n// for one store group, based on each member KB's type, the engine's\n// capabilities, and the search params.\n//\n// The FAQ-vs-document index decision is a PER-KB property (kb.Type), not a\n// property of the multi-KB search's primary KB. groupKBs therefore drives the\n// routing: KBs in the group are split into a FAQ subset (retrieved from the\n// FAQ vector index) and a document subset (retrieved from the default vector\n// index plus the keyword index). Deciding this from the primary KB alone would\n// route every KB in scope into the primary's index — e.g. a FAQ primary would\n// drag a document-type KB into the FAQ index and skip its keyword recall.\n//\n// primary is used only to resolve the shared query embedding model; every KB\n// in a multi-KB search is guaranteed to share a single embedding model by\n// validateSameEmbeddingModel upstream.\nfunc (s *knowledgeBaseService) buildRetrievalParams(\n\tctx context.Context,\n\tretrieveEngine *retriever.CompositeRetrieveEngine,\n\tprimary *types.KnowledgeBase,\n\tgroupKBs []*types.KnowledgeBase,\n\tparams types.SearchParams,\n\tmatchCount int,\n) ([]types.RetrieveParams, error) {\n\tcurrentTenantID := types.MustTenantIDFromContext(ctx)\n\tvar retrieveParams []types.RetrieveParams\n\n\t// Partition the group's KBs by index routing. A KB that does not have\n\t// vector indexing enabled (e.g. wiki-only or graph-only KBs) has no\n\t// embeddings to retrieve from, and typically has no EmbeddingModelID\n\t// configured either; such KBs are skipped for vector retrieval to avoid\n\t// spurious \"model ID cannot be empty\" errors when an agent's retrieval\n\t// scope happens to include them (e.g. KBSelectionMode=all picking up a\n\t// wiki-only KB).\n\tvar faqVectorKBIDs, docVectorKBIDs, docKeywordKBIDs []string\n\t// Document KBs with question generation off must not spend TopK on\n\t// historical question vectors. FAQ KBs are absent from this list: their\n\t// similar-question rows use the same source-id shape.\n\tvar questionOffKBIDs []string\n\tfor _, kb := range groupKBs {\n\t\tif types.QuestionGenerationDisabled(kb) {\n\t\t\tquestionOffKBIDs = append(questionOffKBIDs, kb.ID)\n\t\t}\n\t}\n\t// The query is embedded with the primary's model, or with the first\n\t// vector KB of the group when the primary has none (a wiki primary\n\t// searched together with document KBs): asking the primary for its empty\n\t// model ID failed the whole search.\n\tembeddingKB := primary\n\tif !hasEmbeddingModel(primary) {\n\t\tembeddingKB = nil\n\t}\n\tfor _, kb := range groupKBs {\n\t\tif hasEmbeddingModel(kb) {\n\t\t\tif embeddingKB == nil {\n\t\t\t\tembeddingKB = kb\n\t\t\t}\n\t\t\tif kb.Type == types.KnowledgeBaseTypeFAQ {\n\t\t\t\tfaqVectorKBIDs = append(faqVectorKBIDs, kb.ID)\n\t\t\t} else {\n\t\t\t\tdocVectorKBIDs = append(docVectorKBIDs, kb.ID)\n\t\t\t}\n\t\t}\n\t\t// FAQ KBs are retrieved exclusively via the FAQ vector index and\n\t\t// have no keyword index; only document-type KBs participate in\n\t\t// keyword retrieval.\n\t\tif kb.IsKeywordEnabled() && kb.Type != types.KnowledgeBaseTypeFAQ {\n\t\t\tdocKeywordKBIDs = append(docKeywordKBIDs, kb.ID)\n\t\t}\n\t}\n\n\t// Add vector retrieval params if supported\n\tif retrieveEngine.SupportRetriever(types.VectorRetrieverType) && !params.DisableVectorMatch &&\n\t\t(len(faqVectorKBIDs) > 0 || len(docVectorKBIDs) > 0) {\n\t\tlogger.Info(ctx, \"Vector retrieval supported, preparing vector retrieval parameters\")\n\n\t\tqueryEmbedding, err := s.resolveQueryEmbedding(ctx, embeddingKB, params, currentTenantID)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\n\t\tappendVectorParams := func(kbIDs []string, knowledgeType string) {\n\t\t\tretrieveParams = append(retrieveParams, types.RetrieveParams{\n\t\t\t\tQuery:                         params.QueryText,\n\t\t\t\tEmbedding:                     queryEmbedding,\n\t\t\t\tKnowledgeBaseIDs:              kbIDs,\n\t\t\t\tTopK:                          matchCount,\n\t\t\t\tThreshold:                     params.VectorThreshold,\n\t\t\t\tRetrieverType:                 types.VectorRetrieverType,\n\t\t\t\tKnowledgeIDs:                  params.KnowledgeIDs,\n\t\t\t\tTagIDs:                        params.TagIDs,\n\t\t\t\tKnowledgeType:                 knowledgeType,\n\t\t\t\tExcludeGeneratedQuestionKBIDs: generatedQuestionKBIDs(kbIDs, questionOffKBIDs),\n\t\t\t})\n\t\t}\n\n\t\t// Document KBs use the default vector index; FAQ KBs use the FAQ\n\t\t// index. A group containing both types yields one retrieval param\n\t\t// per index so each KB is queried against the index it was written to.\n\t\tif len(docVectorKBIDs) > 0 {\n\t\t\tappendVectorParams(docVectorKBIDs, \"\")\n\t\t}\n\t\tif len(faqVectorKBIDs) > 0 {\n\t\t\tappendVectorParams(faqVectorKBIDs, types.KnowledgeTypeFAQ)\n\t\t}\n\t\tlogger.Info(ctx, \"Vector retrieval parameters setup completed\")\n\t}\n\n\t// Add keyword retrieval params if supported and any document KB has\n\t// keyword indexing enabled.\n\tif retrieveEngine.SupportRetriever(types.KeywordsRetrieverType) && !params.DisableKeywordsMatch &&\n\t\tlen(docKeywordKBIDs) > 0 {\n\t\tlogger.Info(ctx, \"Keyword retrieval supported, preparing keyword retrieval parameters\")\n\t\tretrieveParams = append(retrieveParams, types.RetrieveParams{\n\t\t\tQuery:                         params.QueryText,\n\t\t\tKnowledgeBaseIDs:              docKeywordKBIDs,\n\t\t\tTopK:                          matchCount,\n\t\t\tThreshold:                     params.KeywordThreshold,\n\t\t\tRetrieverType:                 types.KeywordsRetrieverType,\n\t\t\tKnowledgeIDs:                  params.KnowledgeIDs,\n\t\t\tTagIDs:                        params.TagIDs,\n\t\t\tExcludeGeneratedQuestionKBIDs: generatedQuestionKBIDs(docKeywordKBIDs, questionOffKBIDs),\n\t\t})\n\t\tlogger.Info(ctx, \"Keyword retrieval parameters setup completed\")\n\t}\n\n\treturn retrieveParams, nil\n}\n\n// generatedQuestionKBIDs keeps the off-switch ids that this retrieval param\n// actually searches. An empty result leaves the SQL filter off.\nfunc generatedQuestionKBIDs(searched, disabled []string) []string {\n\tif len(searched) == 0 || len(disabled) == 0 {\n\t\treturn nil\n\t}\n\toff := make(map[string]struct{}, len(disabled))\n\tfor _, id := range disabled {\n\t\toff[id] = struct{}{}\n\t}\n\tvar matched []string\n\tfor _, id := range searched {\n\t\tif _, ok := off[id]; ok {\n\t\t\tmatched = append(matched, id)\n\t\t}\n\t}\n\treturn matched\n}\n\n// resolveQueryEmbedding returns the query embedding for a store group. It\n// reuses params.QueryEmbedding when the caller pre-computed it (the common\n// path — HybridSearch embeds once before fan-out), otherwise it embeds the\n// query text using the embedding model of the supplied KB. For cross-tenant\n// shared KBs the source tenant's embedding model is used so the produced\n// vector is compatible with the index it will be searched against.\nfunc (s *knowledgeBaseService) resolveQueryEmbedding(\n\tctx context.Context,\n\tkb *types.KnowledgeBase,\n\tparams types.SearchParams,\n\tcurrentTenantID uint64,\n) ([]float32, error) {\n\tif len(params.QueryEmbedding) > 0 {\n\t\tlogger.Infof(ctx, \"Using pre-computed query embedding, vector length: %d\", len(params.QueryEmbedding))\n\t\treturn params.QueryEmbedding, nil\n\t}\n\n\tlogger.Infof(ctx, \"Getting embedding model, model ID: %s\", kb.EmbeddingModelID)\n\n\tvar embeddingModel embedding.Embedder\n\tvar err error\n\tif kb.TenantID != currentTenantID {\n\t\tlogger.Infof(ctx, \"Cross-tenant knowledge base detected, using source tenant's embedding model. KB tenant: %d, current tenant: %d\", kb.TenantID, currentTenantID)\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModelForTenant(ctx, kb.EmbeddingModelID, kb.TenantID)\n\t} else {\n\t\tembeddingModel, err = s.modelService.GetEmbeddingModel(ctx, kb.EmbeddingModelID)\n\t}\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"Failed to get embedding model, model ID: %s, error: %v\", kb.EmbeddingModelID, err)\n\t\treturn nil, err\n\t}\n\tlogger.Infof(ctx, \"Embedding model retrieved: %v\", embeddingModel)\n\n\tlogger.Info(ctx, \"Starting to generate query embedding\")\n\tqueryEmbedding, err := embeddingModel.Embed(types.WithEmbedQuery(ctx), params.QueryText)\n\tif err != nil {\n\t\tlogger.Errorf(ctx, \"Failed to embed query text, query text: %s, error: %v\", params.QueryText, err)\n\t\treturn nil, err\n\t}\n\tif err := validateQueryEmbeddingDimension(embeddingModel, len(queryEmbedding)); err != nil {\n\t\tlogger.Errorf(ctx, \"resolveQueryEmbedding: %v\", err)\n\t\treturn nil, err\n\t}\n\tlogger.Infof(ctx, \"Query embedding generated successfully, embedding vector length: %d\", len(queryEmbedding))\n\treturn queryEmbedding, nil\n}\n"
